.preloader{-webkit-box-align:center;-ms-flex-align:center;align-items:center;cursor:default;display:-webkit-box;display:-ms-flexbox;display:flex;height:100%;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;position:fixed;left:0;top:0;width:100%;z-index:9999999;background-color:#fff}
.preloader .animation-preloader{z-index:1000}
.preloader .animation-preloader .spinner{-webkit-animation:spinner 1s infinite linear;animation:spinner 1s infinite linear;border-radius:50%;border:3px solid rgba(0,0,0,.2);border-top-color:#001041;height:9em;margin:0 auto 3.5em auto;width:9em}
@media(max-width:767px){.preloader .animation-preloader .spinner{width:7.5em;height:7.5em;margin:0 auto 1.5em auto}}
.preloader .animation-preloader .txt-loading{font:bold 5em "Exo 2",sans-serif,"Roboto",sans-serif;text-align:center;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}
@media(max-width:767px){.preloader .animation-preloader .txt-loading{font-size:2.5em}}
.preloader .animation-preloader .txt-loading .letters-loading{color:#FF5E14;position:relative}
.preloader .animation-preloader .txt-loading .letters-loading:nth-child(2):before{-webkit-animation-delay:.2s;animation-delay:.2s}
.preloader .animation-preloader .txt-loading .letters-loading:nth-child(3):before{-webkit-animation-delay:.4s;animation-delay:.4s}
.preloader .animation-preloader .txt-loading .letters-loading:nth-child(4):before{-webkit-animation-delay:.6s;animation-delay:.6s}
.preloader .animation-preloader .txt-loading .letters-loading:nth-child(5):before{-webkit-animation-delay:.8s;animation-delay:.8s}
.preloader .animation-preloader .txt-loading .letters-loading::before{-webkit-animation:letters-loading 4s infinite;animation:letters-loading 4s infinite;color:rgb(0,22,89);content:attr(data-text-preloader);left:0;opacity:0;font-family:"Exo 2",sans-serif;position:absolute;top:-3px;-webkit-transform:rotateY(-90deg);transform:rotateY(-90deg)}
.preloader p{font-size:15px;font-weight:600;text-transform:uppercase;letter-spacing:8px;color:#001659}
.preloader .loader{position:fixed;top:0;left:0;width:100%;height:100%;font-size:0;z-index:1;pointer-events:none}
.preloader .loader .row{height:100%}
.preloader .loader .loader-section{padding:0}
.preloader .loader .loader-section .bg{background-color:#fff;height:100%;left:0;width:100%;-webkit-transition:all 800ms cubic-bezier(.77,0,.175,1);transition:all 800ms cubic-bezier(.77,0,.175,1)}
.preloader.loaded .animation-preloader{opacity:0;-webkit-transition:.3s ease-out;transition:.3s ease-out}
.preloader.loaded .loader-section .bg{width:0;-webkit-transition:.7s .3s all cubic-bezier(.1,.1,.1,1);transition:.7s .3s all cubic-bezier(.1,.1,.1,1)}
.animated[data-wow-duration]:not(.wow):not(.wow-done){opacity:1!important;}
#main-content{opacity:1!important;visibility:visible!important;}
body.loading .animated{animation:none!important;}
section.team-member{z-index:0!important;}
.team-member .single-member{overflow:hidden;pointer-events:auto;position:relative;z-index:0;}
.team-member .single-member .hoverly{transition:all 0.4s ease-in-out!important;pointer-events:auto;position:absolute;top:0;bottom:0;left:0;right:0;width:100%;height:100%;background-color:#001659;visibility:hidden;opacity:0;border-radius:10px;}
.team-member .single-member:hover .hoverly{visibility:visible!important;opacity:1!important;}

/* Keep only the active tab pane in layout to prevent invisible panes creating large blank sections. */
.project-tabs-wrapper .tab-content>.kp-tab-panel{display:none;opacity:0;}
.project-tabs-wrapper .tab-content>.kp-tab-panel.active{display:block;opacity:1;}

/* Preserve one-row tabs and keep icon/text centered and visible on all breakpoints. */
.project-tabs-wrapper .nav-pills .nav-item{width:33.333333%!important;flex:0 0 33.333333%;}
.project-tabs-wrapper .nav-pills .nav-item button{display:flex;align-items:center;justify-content:center;min-height:80px;line-height:1.2;padding:0 12px;text-align:center;}
.kp-tab-btn-content{display:inline-flex;align-items:center;justify-content:center;gap:8px;line-height:1.2;}

/* Accordion visibility is controlled by React state; do not depend on missing bootstrap collapse rules. */
.questionanswer .faq-content .faq-ask-list .accordion .kp-accordion-panel{display:none;}
.questionanswer .faq-content .faq-ask-list .accordion .kp-accordion-panel.show{display:block;}
.questionanswer .faq-content .faq-ask-list .accordion .accordion-item .accordion-body p{margin:0;opacity:1;visibility:visible;}

@media (max-width:991px){
	.project-tabs-wrapper .nav-pills .nav-item button{font-size:11px;min-height:62px;padding:8px 6px;}
	.kp-tab-btn-content{gap:4px;}
	.kp-tab-btn-content i{margin-right:0!important;}
